#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=12

# Ticket 14 (.scratch/attendance-v1/issues/14-*.md): one-time setup of the
# Raspberry Pi, Tailscale and GitHub for tag-triggered releases (ADR-0001).
# Run it in Git Bash from anywhere inside the repo. State lives in .env.pi
# (git-ignored), never in the dev .env.
cd "$(git rev-parse --show-toplevel)"
ENV_FILE=".env.pi"

# Run a command on the Pi with a terminal (for sudo and login prompts).
on_pi()   { ssh -t "$PI_USER@$PI_LAN_HOST" "$1"; }
# Run a command on the Pi and capture its output.
from_pi() { ssh "$PI_USER@$PI_LAN_HOST" "$1"; }
# Is a GitHub Actions secret already set?
# Output is captured before grepping: under pipefail, an early-exiting
# `grep -q` can kill the writer with SIGPIPE and fail a check that passed.
has_secret() { local list; list=$(gh secret list 2>/dev/null || true); grep -q "^$1[[:space:]]" <<<"$list"; }
# Print the canonical IANA name for a time zone (e.g. europe/prague → Europe/Prague),
# or fail if it's unknown. It's the same Intl.DateTimeFormat check the app makes
# at start-up, so anything that passes here won't stop the app from starting.
canonical_time_zone() {
  node -e 'process.stdout.write(new Intl.DateTimeFormat("en", { timeZone: process.argv[1] }).resolvedOptions().timeZone)' "$1" 2>/dev/null
}

banner "Raspberry Pi, Tailscale and GitHub setup"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "GitHub CLI"
say "The wizard sets GitHub Actions secrets and variables with the GitHub CLI."
if ! command -v gh >/dev/null 2>&1; then
  open_url "https://cli.github.com"
  step "Install the GitHub CLI, open a new Git Bash, and run this wizard again."
  exit 1
fi
if gh auth status >/dev/null 2>&1; then
  note "Already logged in."
else
  step "Choose GitHub.com, then log in with a web browser and paste the one-time code."
  gh auth login --hostname github.com --git-protocol https --web
fi
GH_LOGIN=$(gh api user --jq .login)
REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
say "Logged in as $GH_LOGIN. Secrets will go to $REPO."
confirm "Is that the right repository?" || { warn "Run the wizard from inside the attendance-system checkout."; exit 1; }

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Pi: connection"
say "From here on the wizard runs the Pi's commands over SSH for you."
note "You'll be asked for the Pi user's password and its sudo password a few times."
ask PI_USER "Pi username (e.g. pi):"
ask PI_LAN_HOST "Pi hostname or IP on your local network (e.g. raspberrypi.local):"
write_env PI_USER "$PI_USER"
write_env PI_LAN_HOST "$PI_LAN_HOST"
step "Checking the Pi is running a 64-bit OS…"
PI_ARCH=$(from_pi "uname -m")
if [[ "$PI_ARCH" != "aarch64" ]]; then
  warn "The Pi reports '$PI_ARCH', not aarch64. The release image is arm64, so install 64-bit Raspberry Pi OS first."
  exit 1
fi
note "64-bit, good."
pause

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Pi: Docker"
if from_pi "command -v docker" >/dev/null 2>&1; then
  note "Docker is already installed."
else
  say "This runs Docker's install script on the Pi (docs.docker.com/engine/install/debian,"
  say "the page Docker points 64-bit Raspberry Pi OS at)."
  note "Docker says the script suits hobby and test machines; for stricter setups it prefers its apt repository."
  confirm "Install Docker on the Pi now?" || exit 1
  on_pi 'curl -fsSL https://get.docker.com -o /tmp/get-docker.sh && sudo sh /tmp/get-docker.sh'
fi
step "Letting your user run docker without sudo…"
on_pi 'sudo usermod -aG docker "$USER"'
step "Checking Docker works (each SSH session is a fresh login, so the group applies)…"
HELLO=$(from_pi "docker run --rm hello-world" 2>&1 || true)
if grep -q "Hello from Docker" <<<"$HELLO"; then
  note "Docker works."
else
  warn "docker run hello-world failed. Fix Docker on the Pi, then re-run the wizard."
  exit 1
fi
pause

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Pi: join the tailnet"
if ! from_pi "command -v tailscale" >/dev/null 2>&1; then
  confirm "Install Tailscale on the Pi now (tailscale.com/install.sh)?" || exit 1
  on_pi 'curl -fsSL https://tailscale.com/install.sh | sh'
fi
say "Joining the tailnet. If a login link appears, open it and approve the Pi."
on_pi 'sudo tailscale up'
TS_STATUS=$(from_pi "tailscale status --json" || true)
# The first DNSName in the JSON is Self's, which comes before Peer.
DETECTED=$(grep -m1 '"DNSName"' <<<"$TS_STATUS" | sed -E 's/.*"DNSName": *"([^"]*)".*/\1/' || true)
DETECTED="${DETECTED%.}"
if [[ -n "$DETECTED" ]] && confirm "The Pi's tailnet name is $DETECTED. Use it?"; then
  PI_HOST="$DETECTED"
else
  open_url "https://login.tailscale.com/admin/machines"
  step "Open the Pi's machine page and copy its full name, ending in .ts.net."
  note "No .ts.net name? Turn on MagicDNS on the DNS page of the admin console."
  ask PI_HOST "Pi's tailnet name:"
fi
write_env PI_HOST "$PI_HOST"
set_var PI_HOST "$PI_HOST"
open_url "https://login.tailscale.com/admin/machines"
step "Find the Pi's row, open its … menu, and choose Disable key expiry."
note "Otherwise the Pi drops off the tailnet when its key expires, and deploys fail."
pause "Done? Press Enter"

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "This PC: join the tailnet"
say "This PC is the Admin's laptop, and the next stages reach the Pi over the tailnet."
if command -v tailscale >/dev/null 2>&1 || [[ -x "/c/Program Files/Tailscale/tailscale.exe" ]]; then
  note "Tailscale is installed here. Make sure it's signed in to the same tailnet."
else
  open_url "https://tailscale.com/download/windows"
  step "Install Tailscale and sign in with the same account you used for the Pi."
fi
pause "Signed in? Press Enter"
step "Checking this PC reaches the Pi at $PI_HOST…"
if ssh "$PI_USER@$PI_HOST" true; then
  note "Reached the Pi over the tailnet."
else
  warn "Couldn't SSH to $PI_HOST. Check Tailscale is connected on both, then re-run."
  exit 1
fi
note "Using another laptop for the Admin area too? Install Tailscale there the same way."
pause

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Pi: HTTPS with Tailscale Serve"
say "Tailscale Serve publishes the app (port 3000 on the Pi) at https://$PI_HOST,"
say "reachable only from your tailnet."
SERVE_HELP=$(from_pi "tailscale serve --help 2>&1" || true)
if ! grep -q -- "--bg" <<<"$SERVE_HELP"; then
  warn "This Pi's Tailscale has no 'serve --bg'. Update it (sudo apt update && sudo apt upgrade tailscale) and re-run."
  exit 1
fi
note "If Serve prints a link to enable HTTPS certificates, open it, approve, then come back."
on_pi 'sudo tailscale serve --bg 3000'
on_pi 'tailscale serve status'
APP_URL="https://$PI_HOST"
write_env APP_URL "$APP_URL"
note "$APP_URL shows an error until the first release (ticket 15) starts the app. That's expected."
pause

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Tailnet policy: the tag:ci tag"
say "Each release joins your tailnet as a temporary device tagged tag:ci."
say "Tags must exist in the policy file before anything can use them."
PI_TS_IP=$(from_pi "tailscale ip -4" | head -n1)
open_url "https://login.tailscale.com/admin/acls/file"
step "Find \"tagOwners\" (add it at the top level if it's missing) and add this entry:"
printf '\n      "tag:ci": ["autogroup:admin"],\n\n'
say "If your policy still has the default rule letting every device reach every"
say "device, that's all. Otherwise also add this to \"grants\", so releases can SSH to the Pi:"
printf '\n      {"src": ["tag:ci"], "dst": ["%s"], "ip": ["tcp:22"]},\n\n' "$PI_TS_IP"
step "Save. The editor checks the syntax and refuses an invalid policy."
pause "Saved? Press Enter"

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Tailscale: OAuth client for releases"
if has_secret TS_OAUTH_SECRET && ! confirm "TS_OAUTH_CLIENT_ID and TS_OAUTH_SECRET are already set. Replace them?"; then
  note "Keeping the existing OAuth client."
else
  open_url "https://login.tailscale.com/admin/settings/trust-credentials"
  step "On Trust credentials, select Credential, then OAuth."
  step "Set Auth Keys to Write, and add the tag tag:ci."
  step "Select Generate credential, and copy the client ID and secret."
  warn "The secret is shown only once, so don't close that page until you've pasted it here."
  ask TS_OAUTH_CLIENT_ID "Paste the client ID:"
  ask_secret TS_OAUTH_SECRET "Paste the client secret:"
  write_env TS_OAUTH_CLIENT_ID "$TS_OAUTH_CLIENT_ID"
  set_secret TS_OAUTH_CLIENT_ID "$TS_OAUTH_CLIENT_ID"
  set_secret TS_OAUTH_SECRET "$TS_OAUTH_SECRET"
  unset TS_OAUTH_SECRET
  step "Back in Tailscale, select Done."
fi
pause

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Deploy SSH key for releases"
DEPLOY_KEY="$HOME/.ssh/attendance_deploy"
if [[ -f "$DEPLOY_KEY" ]]; then
  note "Reusing $DEPLOY_KEY."
else
  mkdir -p "$HOME/.ssh"
  ssh-keygen -q -t ed25519 -N "" -C "attendance-release@github-actions" -f "$DEPLOY_KEY"
  note "Created $DEPLOY_KEY."
fi
DEPLOY_PUB=$(cat "$DEPLOY_KEY.pub")
step "Adding its public half to the Pi's authorized_keys…"
ssh "$PI_USER@$PI_HOST" "mkdir -p ~/.ssh && chmod 700 ~/.ssh && touch ~/.ssh/authorized_keys && chmod 600 ~/.ssh/authorized_keys && { grep -qxF '$DEPLOY_PUB' ~/.ssh/authorized_keys || echo '$DEPLOY_PUB' >> ~/.ssh/authorized_keys; }"
if ssh -i "$DEPLOY_KEY" -o IdentitiesOnly=yes -o BatchMode=yes "$PI_USER@$PI_HOST" true; then
  note "The deploy key logs in."
else
  warn "The deploy key couldn't log in to the Pi. Check ~/.ssh/authorized_keys on the Pi."
  exit 1
fi
step "Recording the Pi's SSH host key, so releases can verify they reached the real Pi…"
PI_SSH_KNOWN_HOSTS=$(ssh-keyscan -t ed25519 "$PI_HOST" 2>/dev/null)
if [[ -z "$PI_SSH_KNOWN_HOSTS" ]]; then
  warn "ssh-keyscan got nothing from $PI_HOST."
  exit 1
fi
# The trailing newline matters: OpenSSH rejects a private key without one.
set_secret PI_SSH_PRIVATE_KEY "$(cat "$DEPLOY_KEY")"$'\n'
set_var PI_SSH_KNOWN_HOSTS "$PI_SSH_KNOWN_HOSTS"
set_var PI_USER "$PI_USER"
pause

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Pi: pull images from GHCR"
IMAGE="ghcr.io/${REPO,,}"
say "Releases push the app image to $IMAGE, and the Pi pulls it from there."
say "GHCR only accepts classic personal access tokens, with the read:packages scope."
DOCKER_AUTH=$(from_pi "cat ~/.docker/config.json 2>/dev/null" || true)
if grep -q "ghcr.io" <<<"$DOCKER_AUTH" && ! confirm "The Pi is already logged in to ghcr.io. Log in again with a new token?"; then
  note "Keeping the Pi's existing GHCR login."
else
  open_url "https://github.com/settings/tokens/new?scopes=read:packages&description=attendance-pi-ghcr"
  step "The note and the read:packages scope are already filled in. Check both."
  step "Pick an Expiration. 'No expiration' means you never redo this; a date means re-running this stage before it."
  step "Select Generate token, then copy it."
  ask_secret GHCR_TOKEN "Paste the token:"
  step "Logging the Pi's Docker in to ghcr.io (the token goes over SSH, never into a file here)…"
  printf '%s' "$GHCR_TOKEN" | ssh "$PI_USER@$PI_HOST" "docker login ghcr.io -u $GH_LOGIN --password-stdin"
  unset GHCR_TOKEN
  note "Docker keeps the login in ~/.docker/config.json on the Pi."
fi
note "The first pull is tested by the first release, because no image exists yet."
pause

# ── 11 ─────────────────────────────────────────────────────────────────────
stage "Pi: production settings"
say "These go in ~/attendance/.env on the Pi (readable only by your user)."
say "A copy stays in .env.pi here, so re-runs keep the same values. Keep this PC safe."
WRITE_PROD_ENV=yes
if from_pi "test -f ~/attendance/.env"; then
  warn "~/attendance/.env already exists on the Pi."
  confirm "Replace it with the values below?" || WRITE_PROD_ENV=no
fi
if [[ "$WRITE_PROD_ENV" == yes ]]; then
  ask ADMIN_EMAIL "Admin email (your login):"
  while :; do
    ask_secret ADMIN_INITIAL_PASSWORD "Admin initial password (12+ characters, no single quotes):"
    if (( ${#ADMIN_INITIAL_PASSWORD} >= 12 )) && [[ "$ADMIN_INITIAL_PASSWORD" != *"'"* ]]; then break; fi
    warn "Use at least 12 characters and no single quotes."
  done
  while :; do
    ask WORKPLACE_TIME_ZONE "Workplace time zone (IANA name, e.g. Europe/Prague):"
    if ! command -v node >/dev/null 2>&1; then
      # Without Node the name can't be checked, so insist on the Area/City shape.
      [[ "$WORKPLACE_TIME_ZONE" == */* ]] && break
      warn "Node isn't installed here, so the name can't be checked. Use the exact Area/City form, e.g. Europe/Prague."
      continue
    fi
    if TZ_CANONICAL=$(canonical_time_zone "$WORKPLACE_TIME_ZONE") && [[ -n "$TZ_CANONICAL" ]]; then
      WORKPLACE_TIME_ZONE="$TZ_CANONICAL"
      break
    fi
    warn "\"$WORKPLACE_TIME_ZONE\" isn't a time zone name the app accepts. Use Area/City, e.g. Europe/Prague."
    note "Full list: https://en.wikipedia.org/wiki/List_of_tz_database_time_zones"
  done
  # Generated once. Re-runs reuse the copy in .env.pi, because the database
  # keeps the password it was first created with.
  POSTGRES_PASSWORD=$(_existing POSTGRES_PASSWORD || openssl rand -hex 24)
  BETTER_AUTH_SECRET=$(_existing BETTER_AUTH_SECRET || openssl rand -hex 32)
  write_env ADMIN_EMAIL "$ADMIN_EMAIL"
  write_env ADMIN_INITIAL_PASSWORD "$ADMIN_INITIAL_PASSWORD"
  write_env WORKPLACE_TIME_ZONE "$WORKPLACE_TIME_ZONE"
  write_env POSTGRES_PASSWORD "$POSTGRES_PASSWORD"
  write_env BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"
  printf "%s\n" \
    "# Production settings, written by scripts/setup-pi.sh. Docker Compose reads this file." \
    "POSTGRES_PASSWORD='$POSTGRES_PASSWORD'" \
    "DATABASE_URL='postgres://attendance:$POSTGRES_PASSWORD@db:5432/attendance'" \
    "WORKPLACE_TIME_ZONE='$WORKPLACE_TIME_ZONE'" \
    "BETTER_AUTH_SECRET='$BETTER_AUTH_SECRET'" \
    "BETTER_AUTH_URL='$APP_URL'" \
    "ADMIN_EMAIL='$ADMIN_EMAIL'" \
    "ADMIN_INITIAL_PASSWORD='$ADMIN_INITIAL_PASSWORD'" \
    | ssh "$PI_USER@$PI_HOST" 'umask 077 && mkdir -p ~/attendance/backups && cat > ~/attendance/.env'
  note "Wrote ~/attendance/.env on the Pi, and made ~/attendance/backups for the nightly dumps."
  note "Changing POSTGRES_PASSWORD after the first release won't change the database's own password."
else
  note "Left the Pi's existing settings alone."
fi
pause

# ── 12 ─────────────────────────────────────────────────────────────────────
stage "Kiosk tablet"
say "On the tablet that will be the Kiosk:"
step "Install the Tailscale app from its app store, and sign in with the same account."
open_url "https://login.tailscale.com/admin/machines"
step "Here, on the Machines page, open the tablet's … menu and choose Disable key expiry."
step "On the tablet, open $APP_URL and add it to the home screen."
